//! Policy pack: per-map learned data compiled into the binary (generated by harness/pack.py).
//!
//! Size is free and lookups are O(1), so map-specific knowledge lives here instead of in
//! code. Format (little-endian): magic "BCPK", version u16, entry count u16, then entries:
//! fingerprint u32 (0 = global fallback), section count u16, sections (tag u8, len u32,
//! bytes). Tags: 1 θ (f32 × learned::P_N), 2 hotspots ((x u8, y u8, weight u8) × n),
//! 3 opening (u8 group indices, slot-major: OPENING_SLOTS × OPENING_LEN, 255 = none).
//! An empty pack (no entries) leaves the bot exactly as compiled.

static PACK: &[u8] = include_bytes!("pack/pack.bin");

pub const TAG_THETA: u8 = 1;
pub const TAG_HOTSPOTS: u8 = 2;
pub const TAG_OPENING: u8 = 3;
pub const OPENING_SLOTS: usize = 6;
pub const OPENING_LEN: usize = 4;

#[derive(Default, Clone, Copy)]
pub struct Entry {
    pub theta: Option<&'static [u8]>,
    pub hotspots: &'static [u8],
    pub opening: &'static [u8],
}

fn u16_at(b: &[u8], i: usize) -> Option<u16> {
    Some(u16::from_le_bytes([*b.get(i)?, *b.get(i + 1)?]))
}

fn u32_at(b: &[u8], i: usize) -> Option<u32> {
    Some(u32::from_le_bytes([*b.get(i)?, *b.get(i + 1)?, *b.get(i + 2)?, *b.get(i + 3)?]))
}

/// The entry for this map, else the global entry, else empty.
#[must_use]
pub fn lookup(fingerprint: u32) -> Entry {
    let b = PACK;
    if b.len() < 8 || &b[..4] != b"BCPK" {
        return Entry::default();
    }
    let Some(n) = u16_at(b, 6) else { return Entry::default() };
    let mut at = 8;
    let (mut global, mut exact) = (None, None);
    for _ in 0..n {
        let (Some(fp), Some(ns)) = (u32_at(b, at), u16_at(b, at + 4)) else { break };
        at += 6;
        let mut e = Entry::default();
        for _ in 0..ns {
            let (Some(&tag), Some(len)) = (b.get(at), u32_at(b, at + 1)) else { return Entry::default() };
            let start = at + 5;
            let Some(data) = b.get(start..start + len as usize) else { return Entry::default() };
            match tag {
                TAG_THETA => e.theta = Some(data),
                TAG_HOTSPOTS => e.hotspots = data,
                TAG_OPENING => e.opening = data,
                _ => {}
            }
            at = start + len as usize;
        }
        if fp == fingerprint {
            exact = Some(e);
        } else if fp == 0 {
            global = Some(e);
        }
    }
    exact.or(global).unwrap_or_default()
}
